import React, { useEffect, useRef, useState } from "react";
import type { VoxideOrbConfig, VoxideStatus } from "./types";

/**
 * The WebGPU orb, as a drop-in layer inside an existing launcher.
 *
 * Three things this component is responsible for and the rest of the widget
 * is not:
 *
 * 1. Keeping the orb module out of the main bundle. The shader alone is 35 KB
 *    and most projects will never turn this on, so `./orb` is only ever
 *    reached through the dynamic import below. Never import it statically
 *    anywhere in the widget.
 *
 * 2. Failing quietly. WebGPU is roughly five browsers in six, and even where
 *    it exists an adapter request can come back empty or a device can be lost
 *    mid-call. Every one of those paths calls `onUnavailable`, and the parent
 *    puts the DOM waveform back. A visitor never sees a hole where the
 *    launcher was.
 *
 * 3. Not re-rendering. Status changes many times during a call and the params
 *    change on every keystroke in the Orb Studio. Recreating a GPUDevice for
 *    either would be catastrophic, so everything live is read through refs and
 *    the renderer is created exactly once.
 */

type OrbCanvasProps = {
  status: VoxideStatus;
  /** The tuned orb, straight from the dashboard. May be undefined or partial. */
  config?: VoxideOrbConfig;
  getInputLevel: () => number;
  getOutputLevel: () => number;
  /** Resolved colour for the current state, blended into the glow and rim. */
  statusColor?: string | null;
  /** Called once when the orb cannot run, or has stopped for good. */
  onUnavailable: (reason: string) => void;
  /**
   * Whether the orb is currently painting.
   *
   * True on the first painted frame, and false again on unmount. Both edges
   * matter: the parent hides its fallback on the rising edge, and a component
   * that only ever reported the rising edge would leave the parent believing a
   * remounted, not-yet-painting orb was still on screen.
   */
  onLiveChange?: (live: boolean) => void;
  /** Extra styles for the canvas. Positioning is owned by the parent. */
  style?: React.CSSProperties;
};

// Resolved lazily and then reused, so a page with several widgets, or a
// launcher that remounts on navigation, imports the module once.
type OrbModule = typeof import("./orb");
let orbModulePromise: Promise<OrbModule> | null = null;

function loadOrbModule(): Promise<OrbModule> {
  if (!orbModulePromise) {
    orbModulePromise = import("./orb").catch((error) => {
      // Let the next mount try again rather than caching a network blip.
      orbModulePromise = null;
      throw error;
    });
  }
  return orbModulePromise;
}

export function OrbCanvas({
  status,
  config,
  getInputLevel,
  getOutputLevel,
  statusColor,
  onUnavailable,
  onLiveChange,
  style,
}: OrbCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [visible, setVisible] = useState(false);

  // Everything the render loop reads, kept current without touching the loop.
  // Callbacks live here too, so a parent passing inline arrows does not tear
  // down a GPUDevice on every render.
  //
  // Written in an effect rather than during render. Mutating a ref while
  // rendering is the documented anti-pattern: under concurrent React a render
  // pass that gets discarded still writes, and the loop can then read values
  // from a tree that was never committed. The cost of doing it properly is at
  // most one frame of lag on a status change, which is invisible.
  const live = useRef({ status, config, getInputLevel, getOutputLevel, statusColor });
  const callbacks = useRef({ onUnavailable, onLiveChange });

  useEffect(() => {
    live.current = { status, config, getInputLevel, getOutputLevel, statusColor };
    callbacks.current = { onUnavailable, onLiveChange };
  });

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    let cancelled = false;
    let dispose: (() => void) | null = null;
    let reported = false;
    let wentLive = false;

    const giveUp = (reason: string) => {
      if (reported) return;
      reported = true;
      if (!cancelled) callbacks.current.onUnavailable(reason);
    };

    // The whole body is guarded, not just the import. A synchronous throw out
    // of createOrbAnimator or createOrbRenderer would otherwise escape as an
    // unhandled rejection, `onUnavailable` would never fire, and the widget
    // would sit forever in "orb enabled, never live" with its fallback hidden.
    (async () => {
      const orb: OrbModule = await loadOrbModule();
      if (cancelled) return;

      // Probe before painting anything. `navigator.gpu` existing is not the
      // same as an adapter being available: a blocklisted driver or a browser
      // out of GPU processes presents the API and then hands back null.
      if (!(await orb.probeOrbSupport())) {
        if (!cancelled) giveUp("WebGPU is not available in this browser");
        return;
      }
      if (cancelled) return;

      // Params are rebuilt from the config on every frame rather than cached,
      // so an edit in the Orb Studio appears on the next frame with no
      // invalidation to get wrong. normalizeOrbParams is a handful of clamps
      // over about forty fields, which is nothing next to a draw call.
      const baseParams = () => orb.normalizeOrbParams(live.current.config ?? {});

      const animator = orb.createOrbAnimator({
        getBase: baseParams,
        getStatus: () => live.current.status,
        getInputLevel: () => live.current.getInputLevel(),
        getOutputLevel: () => live.current.getOutputLevel(),
        getReactivity: () =>
          live.current.config?.reactivity ?? orb.DEFAULT_ORB_REACTIVITY,
        getStatusColor: () => live.current.statusColor ?? null,
        getStatusTint: () =>
          live.current.config?.statusTint ?? orb.DEFAULT_ORB_STATUS_TINT,
      });

      dispose = orb.createOrbRenderer({
        canvas,
        getParams: animator.read,
        getTargetFps: animator.targetFps,
        onReady: () => {
          if (cancelled) return;
          setVisible(true);
          wentLive = true;
          callbacks.current.onLiveChange?.(true);
        },
        onError: (error) => giveUp(error.message),
      });

      if (cancelled) {
        dispose();
        dispose = null;
      }
    })().catch((error: unknown) => {
      giveUp(error instanceof Error ? error.message : String(error));
    });

    return () => {
      cancelled = true;
      dispose?.();
      // Tell the parent the orb is no longer on screen. Without this a
      // remount leaves the parent believing a blank, not-yet-painting canvas
      // is still live: in voice-orb mode it strips the launcher's own fill,
      // border and icon, and nothing at all is painted while the new device
      // and shader come up.
      if (wentLive) callbacks.current.onLiveChange?.(false);
    };
    // Created once. Everything that changes is read through `live`.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <canvas
      ref={canvasRef}
      aria-hidden="true"
      style={{
        display: "block",
        // Held back until the first frame lands, so the parent's waveform can
        // stay up until there is actually something to replace it with.
        opacity: visible ? 1 : 0,
        transition: "opacity 240ms ease",
        pointerEvents: "none",
        ...style,
      }}
    />
  );
}
