//
// The single place editor parameters become GPU memory.
//
// This file and `struct Uniforms` in effect.wgsl describe the same 512 bytes
// from opposite ends. Nothing here is arbitrary and nothing here is reorderable:
// change a slot and the shader reads a different field with no error, which
// shows up as a wrong-looking orb rather than a crash. If you touch the struct,
// touch this in the same commit.

import { ORB_STYLE_FLOW_INDEX, type OrbParams } from "./params";

/** vec4-aligned float count. The struct fills it exactly, so do not shrink it. */
export const ORB_UNIFORM_FLOATS = 128;

/** Where the colour bank starts, after the scalars are padded to 16 bytes. */
const COLOR_BASE = 32;

/**
 * The shader's built-in ramp, used by the legacy flow bank. Not editable, but
 * it occupies the last twelve colour slots and the buffer is sized for it.
 */
const PALETTE_STOPS = [
  "#F7FBFF",
  "#EFF6FD",
  "#E0EEF9",
  "#D4E6F7",
  "#BBD5F3",
  "#A6C7F0",
  "#87B0EB",
  "#6F9EE8",
  "#6F9EE8",
  "#6F9EE8",
  "#6F9EE8",
  "#6F9EE8",
] as const;

/**
 * `#RRGGBB` to a premultiply-ready rgba quad in 0..1.
 *
 * Callers are expected to have run params through `normalizeOrbParams`, but a
 * malformed string here would produce NaN and NaN in a uniform paints an
 * undefined colour rather than failing, so it degrades to black instead.
 */
function rgba(hex: string): [number, number, number, number] {
  const r = Number.parseInt(hex.slice(1, 3), 16);
  const g = Number.parseInt(hex.slice(3, 5), 16);
  const b = Number.parseInt(hex.slice(5, 7), 16);

  if (!Number.isFinite(r) || !Number.isFinite(g) || !Number.isFinite(b)) {
    return [0, 0, 0, 1];
  }
  return [r / 255, g / 255, b / 255, 1];
}

/**
 * Pack one frame's worth of state into `target`.
 *
 * Called once per animation frame per orb, so it allocates nothing: the caller
 * owns the Float32Array and this overwrites it in place.
 */
export function writeOrbUniforms(
  target: Float32Array,
  width: number,
  height: number,
  time: number,
  params: OrbParams,
): void {
  target.fill(0);

  target[0] = width;
  target[1] = height;
  target[2] = time;

  // Scalars, in struct order starting at `speed`. `paletteCount` sits between
  // edgeGlow and glassEnabled and is unused by the shipped presets, hence the 0.
  target.set(
    [
      params.speed,
      params.radius,
      params.zoom,
      params.warp,
      params.ridgeAmt,
      params.sharp,
      params.shade,
      params.sheen,
      params.gloss,
      params.shellMidAlpha,
      params.shellEdgeAlpha,
      params.exposure,
      ORB_STYLE_FLOW_INDEX[params.style],
      params.edgeSoftness,
      params.edgeGlow,
      0, // paletteCount
      params.glassEnabled ? 1 : 0,
      params.glassOpacity,
      params.contourDeform,
      params.bandDensity,
      params.chromaticShift,
      params.metalScale,
      params.metalStretch,
      params.metalAngle,
      params.metalOffset,
      params.metalPhase,
      params.metalEvolution,
      params.metalRoughness,
      params.metalDepth,
    ],
    3,
  );

  const colors = [
    params.colorA,
    params.colorB,
    params.colorC,
    params.colorD,
    params.highlightColor,
    params.shellInner,
    params.shellMid,
    params.shellEdge,
    params.sheenColor,
    params.specColor,
    params.canvasColor,
    params.glowColor,
    ...PALETTE_STOPS,
  ];

  for (let i = 0; i < colors.length; i++) {
    target.set(rgba(colors[i]), COLOR_BASE + i * 4);
  }
}
