// The orb answers the call.
//
// Upstream's orb is a fixed animation: parameters go in once and the sphere
// loops forever. In Voxide the orb is the agent's face, so this module turns
// one static preset into a live performance driven by two things the SDK
// already produces:
//
//   1. `status`, which moves through eight states during a call, and
//   2. mic and agent RMS, which the analyser nodes in VoxideClient already
//      compute for the DOM waveform.
//
// Three rules shaped the design.
//
// The developer's preset always wins. A state never sets an absolute value, it
// nudges the value the developer chose. Someone who tuned a deep violet orb
// gets a deep violet orb in every state, not our idea of what listening should
// look like.
//
// Nothing snaps. Every state change is carried by a critically damped spring,
// so the orb eases between looks and never cuts. Speaking to listening happens
// many times a minute in a real call and a hard cut reads as a bug.
//
// Audio drives a separate layer on top, with an asymmetric envelope. A voice
// has fast onsets and slow decays, and symmetric smoothing makes speech look
// like a sine wave. Attack is quick, release is lazy.

import {
  ORB_NUMERIC_SPECS,
  orbNumericSpec,
  type OrbNumericKey,
  type OrbParams,
} from "./params";
import { prefersReducedMotion } from "./renderer";
import type { VoxideStatus } from "../types";

/**
 * One parameter nudge: scale the developer's value, then offset it.
 *
 * Both forms are needed. `mul` keeps a change proportional to whatever the
 * developer picked, which is right for speed and exposure. `add` can lift a
 * parameter off zero, which is the only way to reach edgeGlow or contourDeform
 * in presets that ship them at 0.
 */
type ParamMod = { mul?: number; add?: number };

type ParamMods = Partial<Record<OrbNumericKey, ParamMod>>;

/** How fast the orb settles into a state, in seconds. Lower is snappier. */
type StateShape = {
  mods: ParamMods;
  smoothTime: number;
  /** Which live level, if any, feeds the audio layer while in this state. */
  audio: "input" | "output" | "none";
  /** Frames per second worth spending here. */
  fps: number;
};

// ── The eight states ────────────────────────────────────────────────────────

const STATE_SHAPES: Record<VoxideStatus, StateShape> = {
  // Asleep but alive. Slow drift, dim, no halo.
  idle: {
    mods: { speed: { mul: 0.55 }, exposure: { mul: 0.82 }, edgeGlow: { add: 0 } },
    smoothTime: 0.7,
    audio: "none",
    fps: 30,
  },

  // Wake word is listening locally. Deliberately calmer than a live call: the
  // widget already draws this distinction with a 2.6s breath against a 1s one,
  // and the orb should not imply a session is running when none is.
  armed: {
    mods: { speed: { mul: 0.68 }, exposure: { mul: 0.9 }, contourDeform: { add: 0.04 } },
    smoothTime: 0.8,
    audio: "none",
    fps: 30,
  },

  // Something is about to happen. Winding up.
  connecting: {
    mods: {
      speed: { mul: 1.35 },
      contourDeform: { add: 0.1 },
      exposure: { mul: 0.95 },
      edgeGlow: { add: 0.1 },
    },
    smoothTime: 0.35,
    audio: "none",
    fps: 60,
  },

  // The caller is talking. Tight, attentive, and everything below this line is
  // driven by their voice rather than by us.
  listening: {
    mods: {
      speed: { mul: 1.05 },
      exposure: { mul: 1.06 },
      edgeGlow: { add: 0.12 },
      radius: { mul: 0.97 },
    },
    smoothTime: 0.3,
    audio: "input",
    fps: 60,
  },

  // Visible effort. The flow churns and the audio layer goes quiet, because
  // there is no audio and faking one is the kind of thing people notice.
  thinking: {
    mods: {
      speed: { mul: 1.5 },
      warp: { mul: 1.35 },
      zoom: { mul: 1.18 },
      ridgeAmt: { mul: 1.15 },
      contourDeform: { add: 0.12 },
      exposure: { mul: 0.96 },
    },
    smoothTime: 0.28,
    audio: "none",
    fps: 60,
  },

  // The agent is talking. Blooming, and driven by its own output.
  speaking: {
    mods: {
      speed: { mul: 1.18 },
      exposure: { mul: 1.14 },
      edgeGlow: { add: 0.18 },
      sheen: { mul: 1.1 },
    },
    smoothTime: 0.25,
    audio: "output",
    fps: 60,
  },

  // Running one of the developer's functions. Reads as working, not talking:
  // detail sharpens instead of the orb swelling.
  executing: {
    mods: {
      speed: { mul: 1.28 },
      ridgeAmt: { mul: 1.3 },
      sharp: { mul: 1.2 },
      contourDeform: { add: 0.06 },
      edgeGlow: { add: 0.08 },
    },
    smoothTime: 0.3,
    audio: "none",
    fps: 60,
  },

  // Something broke. Motion collapses to almost nothing. No flashing, no
  // pulsing: an error state that draws the eye by going still.
  error: {
    mods: { speed: { mul: 0.25 }, exposure: { mul: 0.7 }, edgeGlow: { add: 0 } },
    smoothTime: 0.45,
    audio: "none",
    fps: 30,
  },
};

// ── The audio layer ─────────────────────────────────────────────────────────

/**
 * What a level of 1.0 does, at full reactivity, on top of the state target.
 *
 * Kept modest on purpose. RMS on a normalised voice stream spends most of its
 * time between 0.05 and 0.3, so these are tuned to read at those levels rather
 * than to look impressive against a synthetic 1.0.
 */
const AUDIO_MODS: ParamMods = {
  radius: { add: 0.07 },
  exposure: { mul: 1.45 },
  edgeGlow: { add: 0.4 },
  contourDeform: { add: 0.1 },
  speed: { mul: 1.3 },
};

/**
 * Fast onset, lazy decay. A voice does not fade in.
 *
 * Expressed as time constants in seconds rather than per-frame coefficients,
 * because a per-frame coefficient is only correct at the frame rate it was
 * tuned at. The same utterance would pulse twice as fast on a 120Hz display
 * and half as fast in the states this module throttles to 30fps, and the
 * attack-versus-release asymmetry that the whole design rests on would not
 * survive the trip. These are the old 0.42 and 0.09 coefficients solved back
 * to their 60Hz time constants, so the tuning is unchanged where it was tuned.
 */
const ENVELOPE_ATTACK_TAU = 0.031;
const ENVELOPE_RELEASE_TAU = 0.177;

// ── Spring ──────────────────────────────────────────────────────────────────

type Spring = { value: number; velocity: number };

/**
 * Critically damped step, the standard implicit formulation. Chosen over plain
 * exponential smoothing because it keeps velocity continuous when a target
 * changes mid-flight, which during a real call happens constantly, and because
 * critical damping cannot overshoot: an orb that wobbles past its target and
 * back looks like a bug rather than a flourish.
 */
function springStep(spring: Spring, target: number, smoothTime: number, dt: number): number {
  if (smoothTime <= 0 || dt <= 0) {
    spring.value = target;
    spring.velocity = 0;
    return target;
  }

  const omega = 2 / smoothTime;
  const x = omega * dt;
  const decay = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x);

  const change = spring.value - target;
  const temp = (spring.velocity + omega * change) * dt;

  spring.velocity = (spring.velocity - omega * temp) * decay;
  spring.value = target + (change + temp) * decay;

  // Settle rather than asymptote forever, so an idle orb stops writing new
  // uniform values that are identical to the last ones.
  if (Math.abs(spring.value - target) < 1e-4 && Math.abs(spring.velocity) < 1e-3) {
    spring.value = target;
    spring.velocity = 0;
  }

  return spring.value;
}

// ── Colour ──────────────────────────────────────────────────────────────────

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function parseHex(hex: string): [number, number, number] | null {
  if (!/^#[0-9a-f]{6}$/i.test(hex)) return null;
  return [
    Number.parseInt(hex.slice(1, 3), 16),
    Number.parseInt(hex.slice(3, 5), 16),
    Number.parseInt(hex.slice(5, 7), 16),
  ];
}

function toHex(rgb: [number, number, number]): string {
  return `#${rgb
    .map((c) => Math.round(clamp(c, 0, 255)).toString(16).padStart(2, "0"))
    .join("")}`.toUpperCase();
}

function mixHex(from: string, to: string, amount: number): string {
  if (amount <= 0) return from;
  const a = parseHex(from);
  const b = parseHex(to);
  if (!a || !b) return from;
  return toHex([
    a[0] + (b[0] - a[0]) * amount,
    a[1] + (b[1] - a[1]) * amount,
    a[2] + (b[2] - a[2]) * amount,
  ]);
}

// ── The animator ────────────────────────────────────────────────────────────

export type OrbAnimatorOptions = {
  /** The developer's tuned preset. Read every frame so edits appear live. */
  getBase: () => OrbParams;
  getStatus: () => VoxideStatus;
  /** 0..1 RMS from the caller's mic. */
  getInputLevel: () => number;
  /** 0..1 RMS from the agent's own speech. */
  getOutputLevel: () => number;
  /**
   * How far audio is allowed to push the orb, 0..1. At 0 the orb is a still
   * animation that only changes with agent state.
   */
  getReactivity?: () => number;
  /**
   * The colour for the current state, if the developer configured status
   * colours. Blended into the glow and rim so the orb honours the same setting
   * the launcher already does.
   */
  getStatusColor?: () => string | null;
  /** How strongly the status colour tints the orb, 0..1. */
  getStatusTint?: () => number;
};

export type OrbAnimator = {
  /** Called once per rendered frame. Returns the params to hand the GPU. */
  read: () => OrbParams;
  /** What the renderer should be spending on the current state. */
  targetFps: () => number;
};

export const DEFAULT_ORB_REACTIVITY = 0.55;
export const DEFAULT_ORB_STATUS_TINT = 0.35;

/**
 * Every parameter a state or the audio layer is allowed to touch. Springs are
 * allocated once for these and nothing else, so a preset's other twenty-odd
 * parameters pass through untouched and cost nothing per frame.
 */
const ANIMATED_KEYS: readonly OrbNumericKey[] = (() => {
  const keys = new Set<OrbNumericKey>(Object.keys(AUDIO_MODS) as OrbNumericKey[]);
  for (const shape of Object.values(STATE_SHAPES)) {
    for (const key of Object.keys(shape.mods) as OrbNumericKey[]) keys.add(key);
  }
  // Only keep keys that are real, tunable parameters.
  return ORB_NUMERIC_SPECS.filter((spec) => keys.has(spec.key)).map((spec) => spec.key);
})();

function applyMod(base: number, mod: ParamMod | undefined, weight: number): number {
  if (!mod) return base;
  const mul = mod.mul === undefined ? 1 : 1 + (mod.mul - 1) * weight;
  const add = (mod.add ?? 0) * weight;
  return base * mul + add;
}

export function createOrbAnimator(options: OrbAnimatorOptions): OrbAnimator {
  const {
    getBase,
    getStatus,
    getInputLevel,
    getOutputLevel,
    getReactivity,
    getStatusColor,
    getStatusTint,
  } = options;

  const reducedMotion = prefersReducedMotion();

  const springs = new Map<OrbNumericKey, Spring>();
  let envelope = 0;
  let lastFrame = 0;
  let currentFps = 30;

  // Reused so a 60fps loop allocates one object per frame instead of forty.
  let out: OrbParams | null = null;

  function read(): OrbParams {
    const now = performance.now();
    // First frame has no dt, and a tab that was hidden for a minute must not
    // hand the spring a 60 second step. Clamp to two frames at 30fps.
    const dt = lastFrame === 0 ? 0 : Math.min((now - lastFrame) / 1000, 0.067);
    lastFrame = now;

    const base = getBase();
    const status = getStatus();
    const shape = STATE_SHAPES[status] ?? STATE_SHAPES.idle;
    currentFps = shape.fps;

    // Reduced motion still changes look per state, it just gets there instantly
    // and never pulses with the voice.
    const smoothTime = reducedMotion ? 0 : shape.smoothTime;
    const reactivity = reducedMotion
      ? 0
      : clamp(getReactivity ? getReactivity() : DEFAULT_ORB_REACTIVITY, 0, 1);

    // Audio envelope.
    let level = 0;
    if (shape.audio === "input") level = getInputLevel();
    else if (shape.audio === "output") level = getOutputLevel();
    if (!Number.isFinite(level)) level = 0;
    level = clamp(level, 0, 1);

    const tau = level > envelope ? ENVELOPE_ATTACK_TAU : ENVELOPE_RELEASE_TAU;
    // Frame-rate independent one-pole. At dt = 1/60 this reproduces the
    // original 0.42 and 0.09 coefficients to three decimals.
    envelope += (level - envelope) * (dt > 0 ? 1 - Math.exp(-dt / tau) : 1);
    const audioWeight = envelope * reactivity;

    if (!out) out = { ...base };
    else Object.assign(out, base);

    for (const key of ANIMATED_KEYS) {
      const spec = orbNumericSpec(key);
      if (!spec) continue;

      // State target first, sprung, so switching states eases.
      const stateTarget = clamp(applyMod(base[key], shape.mods[key], 1), spec.min, spec.max);

      let spring = springs.get(key);
      if (!spring) {
        spring = { value: stateTarget, velocity: 0 };
        springs.set(key, spring);
      }
      const settled = springStep(spring, stateTarget, smoothTime, dt);

      // Audio rides on top of the sprung value and is not itself sprung: the
      // envelope above is already its smoothing, and springing it twice turns
      // speech into a slow swell.
      const withAudio = applyMod(settled, AUDIO_MODS[key], audioWeight);

      out[key] = clamp(withAudio, spec.min, spec.max);
    }

    // Tint the halo and rim toward the developer's configured status colour, so
    // one orb honours the same setting that already colours the launcher.
    const tint = clamp(getStatusTint ? getStatusTint() : DEFAULT_ORB_STATUS_TINT, 0, 1);
    const statusColor = tint > 0 && getStatusColor ? getStatusColor() : null;
    if (statusColor) {
      out.glowColor = mixHex(base.glowColor, statusColor, tint);
      out.shellEdge = mixHex(base.shellEdge, statusColor, tint * 0.6);
    }

    return out;
  }

  return {
    read,
    targetFps: () => currentFps,
  };
}
